/* @autogenerated */
import { Signal, TemplateRef, WritableSignal } from '@angular/core';
import type { ActionContainerComponent } from './action-container.component';

/** Contrato que el contenedor espera de cada acción; las acciones nuevas extienden `BaseAction`/`ConfirmAction`. */
export interface Action {
  readonly name: string;
  readonly contextual: boolean;
  readonly multiple: boolean;
  default: Signal<boolean>;

  label: Signal<string>;
  icon: Signal<string>;
  tooltip: Signal<string>;
  title: Signal<string>;

  visible(items: any[]): Signal<boolean>;
  enabled(items: any[]): Signal<boolean>;

  run(): void;

  container: WritableSignal<ActionContainerComponent | undefined>;
  selection: Signal<any[]>;
  render: Signal<TemplateRef<any> | undefined>;
}

/** Traduce un elemento a la clave que se guarda en la URL y viceversa. */
export interface ItemMapper<T> {
  display(item: T): string;
  load(code: string): Signal<T>;
}
